#include "stdlib/blas/base/dgemm.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/xerbla.h"

/**
* Performs the matrix-matrix operation `C = alpha*op(A)*op(B) + beta*C`, where `op(X)` is either `op(X) = X` or `op(X) = X^T`, `alpha` and `beta` are scalars, and `A`, `B`, and `C` are matrices, with `op(A)` an `M`-by-`K` matrix, `op(B)` a `K`-by-`N` matrix, and `C` an `M`-by-`N` matrix.
*
* @param layout   storage layout
* @param transA   specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param transB   specifies whether `B` should be transposed, conjugate-transposed, or not transposed
* @param M        number of rows in `op(A)` and `C`
* @param N        number of columns in `op(B)` and `C`
* @param K        number of columns in `op(A)` and rows in `op(B)`
* @param alpha    scalar constant
* @param A        first matrix
* @param LDA      leading dimension of `A`
* @param B        second matrix
* @param LDB      leading dimension of `B`
* @param beta     scalar constant
* @param C        result matrix
* @param LDC      leading dimension of `C`
*/
void API_SUFFIX(c_dgemm)( const CBLAS_LAYOUT layout, const CBLAS_TRANSPOSE transA, const CBLAS_TRANSPOSE transB, const CBLAS_INT M, const CBLAS_INT N, const CBLAS_INT K, const double alpha, const double *A, const CBLAS_INT LDA, const double *B, const CBLAS_INT LDB, const double beta, double *C, const CBLAS_INT LDC ) {
	CBLAS_INT strideA1;
	CBLAS_INT strideA2;
	CBLAS_INT strideB1;
	CBLAS_INT strideB2;
	CBLAS_INT strideC1;
	CBLAS_INT strideC2;
	CBLAS_INT minLDA;
	CBLAS_INT minLDB;
	CBLAS_INT minLDC;

	// Perform input argument validation...
	if ( layout != CblasRowMajor && layout != CblasColMajor ) {
		c_xerbla( 1, "c_dgemm", "Error: invalid argument. First argument must be a valid storage layout. Value: `%d`.", layout );
		return;
	}
	if ( transA != CblasNoTrans && transA != CblasTrans && transA != CblasConjTrans ) {
		c_xerbla( 2, "c_dgemm", "Error: invalid argument. Second argument must be a valid transpose operation. Value: `%d`.", transA );
		return;
	}
	if ( transB != CblasNoTrans && transB != CblasTrans && transB != CblasConjTrans ) {
		c_xerbla( 3, "c_dgemm", "Error: invalid argument. Third argument must be a valid transpose operation. Value: `%d`.", transB );
		return;
	}
	if ( M < 0 ) {
		c_xerbla( 4, "c_dgemm", "Error: invalid argument. Fourth argument must be a nonnegative integer. Value: `%d`.", M );
		return;
	}
	if ( N < 0 ) {
		c_xerbla( 5, "c_dgemm", "Error: invalid argument. Fifth argument must be a nonnegative integer. Value: `%d`.", N );
		return;
	}
	if ( K < 0 ) {
		c_xerbla( 6, "c_dgemm", "Error: invalid argument. Sixth argument must be a nonnegative integer. Value: `%d`.", K );
		return;
	}
	// Compute the minimum required leading dimensions based on storage layout...
	if ( layout == CblasColMajor ) {
		// For column-major, the leading dimension equals the number of rows of the stored matrix:
		minLDA = ( transA == CblasNoTrans ) ? M : K;
		minLDB = ( transB == CblasNoTrans ) ? K : N;
		minLDC = M;
	} else {
		// For row-major, the leading dimension equals the number of columns of the stored matrix:
		minLDA = ( transA == CblasNoTrans ) ? K : M;
		minLDB = ( transB == CblasNoTrans ) ? N : K;
		minLDC = N;
	}
	if ( minLDA < 1 ) {
		minLDA = 1;
	}
	if ( LDA < minLDA ) {
		c_xerbla( 9, "c_dgemm", "Error: invalid argument. Ninth argument must be greater than or equal to max(1,%d). Value: `%d`.", minLDA, LDA );
		return;
	}
	if ( minLDB < 1 ) {
		minLDB = 1;
	}
	if ( LDB < minLDB ) {
		c_xerbla( 11, "c_dgemm", "Error: invalid argument. Eleventh argument must be greater than or equal to max(1,%d). Value: `%d`.", minLDB, LDB );
		return;
	}
	if ( minLDC < 1 ) {
		minLDC = 1;
	}
	if ( LDC < minLDC ) {
		c_xerbla( 14, "c_dgemm", "Error: invalid argument. Fourteenth argument must be greater than or equal to max(1,%d). Value: `%d`.", minLDC, LDC );
		return;
	}
	// Check whether we can avoid computation altogether...
	if ( M == 0 || N == 0 || ( ( alpha == 0.0 || K == 0 ) && beta == 1.0 ) ) {
		return;
	}
	// Compute strides based on storage layout...
	if ( layout == CblasColMajor ) {
		strideA1 = 1;
		strideA2 = LDA;
		strideB1 = 1;
		strideB2 = LDB;
		strideC1 = 1;
		strideC2 = LDC;
	} else { // layout == CblasRowMajor
		strideA1 = LDA;
		strideA2 = 1;
		strideB1 = LDB;
		strideB2 = 1;
		strideC1 = LDC;
		strideC2 = 1;
	}
	API_SUFFIX(c_dgemm_ndarray)( transA, transB, M, N, K, alpha, A, strideA1, strideA2, 0, B, strideB1, strideB2, 0, beta, C, strideC1, strideC2, 0 );
	return;
}
